; print time (minutes:seconds)

print_minute = *
	ldy	v_minute
	cpy	old_minute
	beq	print_second
	sty	old_minute
	; mwa #scr+35 zARG0
	lda	#<(scr+35)
	sta	zARG0
	lda	#>(scr+35)
	sta	zARG0+1
	tya
	jsr	printhex

print_second = *
	ldy	v_second
	cpy	old_second
	beq	print_order
	sty	old_second
	; mwa #scr+38 zARG0
	lda	#<(scr+38)
	sta	zARG0
	lda	#>(scr+38)
	sta	zARG0+1
	tya
	jsr	printhex

; print pattern order and row

print_order = *
	ldy	v_ord
	cpy	old_ord
	beq	print_row
	sty	old_ord
	; mwa #scr+118 zARG0
	lda	#<(scr+118)
	sta	zARG0
	lda	#>(scr+118)
	sta	zARG0+1
	tya
	jsr	printhex

print_row = *
	ldy	smc_abeat
	cpy	old_abeat
	beq	print_speed
	sty	old_abeat
	; mwa #scr+198 zARG0
