vbis2 = *
	lda	trackn_audf,x
	cmp	old_audf,x
	beq	vbis2_a	; skip updating the missiles, they will use the same position
	sta	old_audf,x

	eor	#$ff
	; :2 lsr @
	.repeat 2, I
	lsr	a
	.endrep
	; add #$75
	clc
	adc	#$75
	sta	mistmp,x
vbis2_a = *
	inc	zINDEX
	inx
	stx	zTMP1
	cpx	#4

