; infos position on screen

infoposLo = *
	; :8 dta <[scr+#*120+40]
	.repeat 8, I
	.byte	<(scr+I*120+40)
	.endrep
infoposHi = *
	; :8 dta >[scr+#*120+40]
	.repeat 8, I
	.byte	>(scr+I*120+40)
	.endrep

; display lists related stuff

dlist = *
	.byte	$70, $70, $30
	.byte	$42
	.word	scr
	; :11 dta $02
	.repeat 11, I
	.byte	$02
	.endrep
	.byte	$82
	; :12 dta $02
	.repeat 12, I
	.byte	$02
	.endrep
	.byte	$41
	.word	dlist

; some extra vbi data

; line counter spacing table for instrument speed from 1 to 6
tabpp = *
	.byte	156, 78, 52, 39, 19, 9, 4

;fixP 		dta 0

;tabppFixP  	dta 0,0,0,0,$80,$c0,$e0         ; adjustments for music speed

; old data used for buffered frame updates as references

oldvbi = *
	.word	0

; song timer, songline position and channel volumes of the current frame (before old_memory, which start_flush fills)

v_frame = *
	ORG	*+1
v_second = *
	ORG	*+1
v_minute = *
	ORG	*+1
v_region = *
	ORG	*+1
v_ord = *
	ORG	*+1
v_volume = *
	ORG	*+TRACKS

old_memory = *

old_ord = *
	ORG	*+1
old_abeat = *
	ORG	*+1
old_second = *
	ORG	*+1
old_minute = *
	ORG	*+1
old_audf = *
	ORG	*+TRACKS
old_audc = *
	ORG	*+TRACKS
;old_note     	org *+TRACKS
; yes that's shit but I cannot find a better way around for now...
old_off = *
	ORG	*+TRACKS
old_volume = *
	ORG	*+TRACKS
old_speed = *
	ORG	*+1
old_audctl = *
	ORG	*+1
old_skctl = *
	ORG	*+1

.if STEREOMODE=1
old_audctl2 = *
	ORG	*+1
old_skctl2 = *
	ORG	*+1
.endif

; temporary missiles location

mistmp = *
	ORG	*+TRACKS

; load font into memory, this was put at the very end to avoid overwriting other data

	ORG	FONT	; characters set memory location
	.incbin "font.fnt"	; some cool looking font
	RUN	start
	OPT_H	0	; RMT module is standard Atari binary file already
	.incbin "music.rmt"	; include music RMT module
	OPT_H	1

; that's all... ;-)

